71	    allClubs,
72	    onUpdatePlayer,
73	}: Props) => {
74	    const [submitting, setSubmitting] = useState(false);
75	    const initialExtraEmails = extraEmails.map(
76	        (playerEmail) => playerEmail.email,
77	    );
78	    const bornYear = player.born ?? undefined;
79	
80	    const form = useForm<PlayerProfileFormValues>({
81	        initialValues: {
82	            name: player.name ?? '',
83	            accountEmail: accountEmail ?? player.accountEmail ?? '',
84	            anonymous: player.anonymous ?? false,
85	            goalie: player.goalie ?? false,
86	            retired: Boolean(player.finished),
87	            extraEmails: initialExtraEmails.length ? initialExtraEmails : [''],
88	            addedExtraEmails: [],
89	            removedExtraEmails: [],
90	            born: bornYear,
91	            countries: countries.map((country) => country.country.fifaCode),
92	            clubs: clubs.map((club) => club.clubId.toString()),
93	            comment: player.comment ?? '',
