104	            autoClose: false,
105	            withCloseButton: false,
106	        });
107	
108	        setSubmitting(true);
109	        try {
110	            const nextExtraEmails = values.extraEmails
111	                .map((email) => email.trim())
112	                .filter((email) => email.length > 0);
113	            const addedExtraEmails = nextExtraEmails.filter(
114	                (email) => !initialExtraEmails.includes(email),
115	            );
116	            const removedExtraEmails = initialExtraEmails.filter(
117	                (email) => !nextExtraEmails.includes(email),
118	            );
119	            const { retired, clubs, ...rest } = values;
120	            const finished = retired ? (player.finished ?? new Date()) : null;
121	
122	            await onUpdatePlayer(player.id, {
123	                ...rest,
124	                clubs: clubs.map((clubId) => Number(clubId)),
125	                finished,
126	                extraEmails: nextExtraEmails,
127	                addedExtraEmails,
128	                removedExtraEmails,
129	            });
130	
131	            notifications.update({
132	                id,
133	                color: 'teal',
134	                title: 'Profile updated',
135	                message: 'Profile updated successfully',
136	                icon: <IconCheck size={config.notificationIconSize} />,
137	                loading: false,
138	                autoClose: config.notificationAutoClose,
139	            });
