32	import type { PayDebtInput, PayDebtProxy } from '@/types/actions/PayDebt';
33	import type { PlayerDebtsType } from '@/types/DebtType';
34	
35	export interface MoneyFormProps {
36	    playerDebts: PlayerDebtsType[];
37	    payDebt: PayDebtProxy;
38	}
39	
40	export const MoneyForm = ({ playerDebts, payDebt }: MoneyFormProps) => {
41	    const [submittingPlayerId, setSubmittingPlayerId] = useState<number | null>(
42	        null,
43	    );
44	
45	    return (
46	        <Container
47	            size="lg"
48	            py="lg"
49	        >
50	            <Paper w="100%">
51	                <Stack gap="md">
