53	                    {playerDebts.map((row) => (
54	                        <DebtRow
55	                            key={row.player.id}
56	                            row={row}
57	                            payDebt={payDebt}
58	                            submittingPlayerId={submittingPlayerId}
59	                            setSubmittingPlayerId={setSubmittingPlayerId}
60	                        />
61	                    ))}
62	                </Stack>
63	            </Paper>
64	        </Container>
65	    );
66	};
67	
68	const PayDebtFormSchema = z.object({
69	    checkedIds: z.array(z.number().int()).min(1),
70	});
71	
72	type PayDebtFormValues = z.infer<typeof PayDebtFormSchema>;
73	
74	interface DebtRowProps {
75	    row: PlayerDebtsType;
76	    payDebt: PayDebtProxy;
77	    submittingPlayerId: number | null;
78	    setSubmittingPlayerId: React.Dispatch<React.SetStateAction<number | null>>;
79	}
80	
81	const DebtRow = ({
82	    row,
83	    payDebt,
84	    submittingPlayerId,
85	    setSubmittingPlayerId,
86	}: DebtRowProps) => {
87	    const router = useRouter();
88	    const totalDebt = row.debts.reduce((sum, d) => sum + d.amount, 0);
89	
90	    const form = useForm<PayDebtFormValues>({
91	        initialValues: {
92	            checkedIds: row.debts.map((d) => d.gameDay.id),
93	        },
94	        validate: zod4Resolver(PayDebtFormSchema),
95	    });
96	
97	    const checkedDebts = row.debts.filter((d) =>
98	        form.values.checkedIds.includes(d.gameDay.id),
99	    );
100	    const totalAmount = checkedDebts.reduce((sum, d) => sum + d.amount, 0);
101	
102	    const toggleDebt = (gameDayId: number) => {
103	        const current = form.values.checkedIds;
104	        form.setFieldValue(
105	            'checkedIds',
106	            current.includes(gameDayId)
107	                ? current.filter((id) => id !== gameDayId)
108	                : [...current, gameDayId],
109	        );
110	    };
111	
112	    const handlePay = async (values: PayDebtFormValues) => {
113	        const notificationId = `money-paid-${row.player.id}`;
114	        const gameDayIds = values.checkedIds;
115	        const amount = row.debts
116	            .filter((d) => gameDayIds.includes(d.gameDay.id))
117	            .reduce((sum, d) => sum + d.amount, 0);
118	
119	        const payload: PayDebtInput = {
120	            playerId: row.player.id,
121	            amount,
122	            gameDayIds,
123	        };
124	
125	        notifications.show({
126	            id: notificationId,
127	            loading: true,
128	            title: 'Recording payment',
129	            message: `Recording ${formatCurrency(amount)} for ${row.player.name ?? 'player'} across ${gameDayIds.length} game(s)...`,
130	            autoClose: false,
131	            withCloseButton: false,
132	        });
133	
134	        setSubmittingPlayerId(row.player.id);
135	        try {
136	            const result = await payDebt(payload);
137	
138	            notifications.update({
139	                id: notificationId,
140	                color: 'teal',
141	                title: 'Payment recorded',
142	                message: `Created ${result.transactionIds.length} transaction(s). New balance: ${formatCurrencySigned(result.resultingBalance)}.`,
143	                icon: <IconCheck size={config.notificationIconSize} />,
144	                loading: false,
145	                autoClose: config.notificationAutoClose,
146	            });
147	
148	            router.refresh();
149	        } catch (error) {
150	            captureUnexpectedError(error, {
151	                layer: 'client',
152	                component: 'MoneyForm',
153	                action: 'payDebt',
154	                route: '/footy/admin/money',
155	                extra: {
156	                    playerId: row.player.id,
157	                    amount,
158	                    gameDayCount: gameDayIds.length,
159	                },
160	            });
161	            const message =
162	                error instanceof Error
163	                    ? error.message
164	                    : 'Failed to record payment';
165	            notifications.update({
166	                id: notificationId,
167	                color: 'red',
168	                title: 'Error',
169	                message,
170	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
171	                loading: false,
172	                autoClose: false,
173	                withCloseButton: true,
174	            });
175	        } finally {
176	            setSubmittingPlayerId(null);
177	        }
178	    };
179	
180	    return (
181	        <Box
182	            component="form"
183	            onSubmit={form.onSubmit(handlePay)}
184	            bd="1px solid var(--mantine-color-gray-3)"
185	            p="sm"
186	            bdrs="sm"
187	        >
188	            <Stack gap="sm">
189	                <Group wrap="nowrap">
190	                    <Anchor href={`/footy/player/${row.player.id}`}>
191	                        <Image
192	                            w={48}
193	                            h={48}
194	                            radius="xl"
195	                            src={`/api/footy/player/${row.player.id}/mugshot`}
196	                            alt={row.player.name ?? `Player ${row.player.id}`}
197	                        />
198	                    </Anchor>
199	                    <Stack
200	                        gap={0}
201	                        style={{ flex: 1, minWidth: 0 }}
202	                    >
203	                        <Anchor href={`/footy/player/${row.player.id}`}>
204	                            {row.player.name ?? `Player ${row.player.id}`}
205	                        </Anchor>
206	                        <Text
207	                            size="sm"
208	                            c={getBalanceColor(-totalDebt)}
209	                        >
210	                            Total debt: {formatCurrencySigned(-totalDebt)} (
211	                            {row.debts.length} game
212	                            {row.debts.length === 1 ? '' : 's'})
213	                        </Text>
214	                    </Stack>
215	                </Group>
216	
217	                {row.debts.length > 0 && (
218	                    <Stack gap="xs">
219	                        {row.debts.map((debt) => (
220	                            <Checkbox
221	                                key={debt.gameDay.id}
222	                                checked={form.values.checkedIds.includes(
223	                                    debt.gameDay.id,
224	                                )}
225	                                onChange={() => toggleDebt(debt.gameDay.id)}
226	                                label={
227	                                    <Group gap="xs">
228	                                        <GameDayLink gameDay={debt.gameDay} />
229	                                        <Text size="sm">
230	                                            {formatCurrency(debt.amount)}
231	                                        </Text>
232	                                    </Group>
233	                                }
234	                            />
235	                        ))}
236	                    </Stack>
237	                )}
238	
239	                <Group
240	                    wrap="nowrap"
241	                    justify="flex-end"
242	                >
243	                    <Text
244	                        size="sm"
245	                        fw={500}
246	                    >
247	                        {formatCurrency(totalAmount)}
248	                    </Text>
249	                    <Button
250	                        type="submit"
251	                        disabled={
252	                            form.values.checkedIds.length === 0 ||
253	                            submittingPlayerId === row.player.id
254	                        }
255	                        loading={submittingPlayerId === row.player.id}
256	                    >
257	                        Paid
258	                    </Button>
259	                </Group>
260	            </Stack>
261	        </Box>
262	    );
263	};
